export const MIGRATIONS: { platform: Migration[]; shop: Migration[] } = {"platform":[{"version":"0001_init","sql":"-- =====================================================================================================\n--  BillPoodum — Turso (libSQL / SQLite) schema: platform database (one)\n-- =====================================================================================================\n--  GENERATED by backend/scripts/gen-sqlite.mjs from server/catalyst/schema.sql — do not edit by hand.\n--  To change a table: edit schema.sql, run the generator, and add the difference as a new migration file\n--  backend/migrations/platform/NNNN_<what>.sql (ALTER TABLE …). The tests check the migrations add up to this file.\n--\n--  Same tables, columns and relations as the approved design (see server/catalyst/TABLES.md). Mapping:\n--    Catalyst ROWID              → \"id\" INTEGER PRIMARY KEY AUTOINCREMENT (never reused; the API calls it ROWID)\n--    CREATEDTIME / MODIFIEDTIME  → \"created_at\" / \"updated_at\"  TEXT, ISO-8601 UTC (set automatically)\n--    VARCHAR(n) / TEXT           → TEXT  (max length checked by the API, so it can grow without a table rebuild)\n--    INT / BIGINT / FK ids       → INTEGER   · money in paise, qty in thousandths, % in basis points\n--    BOOLEAN                     → INTEGER 0 / 1\n--    DATE / DATETIME             → TEXT  YYYY-MM-DD / ISO-8601 UTC (sorts and compares correctly)\n--    ENCRYPTED                   → TEXT holding AES-256-GCM ciphertext (the API encrypts with SECRETS_KEY)\n--    Fixed lists (enums)         → INTEGER codes from server/catalyst/enums.ts (CHECK >= 1 only, so a new\n--                                   value never needs a migration). Never renumber; add at the end.\n--    FK → x CASCADE / NULL       → REFERENCES x(\"id\") ON DELETE CASCADE / SET NULL — only when x is in this\n--                                   database; a reference to the other database is a plain INTEGER.\n--  The API turns on foreign keys (\"PRAGMA foreign_keys = ON\") on every connection.\n-- =====================================================================================================\n\nCREATE TABLE IF NOT EXISTS \"platform_admins\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"name\"                     TEXT     NOT NULL,  -- max 120\n  \"username\"                 TEXT     NOT NULL UNIQUE,  -- max 40\n  \"email\"                    TEXT,  -- max 150\n  \"password_hash\"            TEXT     NOT NULL,  -- max 100 · bcrypt\n  \"token_version\"            INTEGER  NOT NULL DEFAULT 1,  -- +1 on password change / sign out everywhere\n  \"failed_logins\"            INTEGER  NOT NULL DEFAULT 0,\n  \"locked_until\"             TEXT,\n  \"role\"                     INTEGER  NOT NULL CHECK (\"role\" >= 1),  -- AdminRole: 1 super, 2 manager, 3 support\n  \"is_active\"                INTEGER  NOT NULL DEFAULT 1 CHECK (\"is_active\" IN (0, 1)),\n  \"last_login_at\"            TEXT,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"platform_admins_updated_at\" AFTER UPDATE ON \"platform_admins\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"platform_admins\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\n\n-- Plans the product sells (today: price per branch per month). Lets pricing change without code.\nCREATE TABLE IF NOT EXISTS \"plans\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"code\"                     TEXT     NOT NULL UNIQUE,  -- max 30 · standard | …\n  \"name\"                     TEXT     NOT NULL,  -- max 80\n  \"price_per_branch_month_minor\" INTEGER  NOT NULL,\n  \"features_json\"            TEXT,  -- feature keys included\n  \"is_active\"                INTEGER  NOT NULL DEFAULT 1 CHECK (\"is_active\" IN (0, 1)),\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"plans_updated_at\" AFTER UPDATE ON \"plans\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"plans\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\n\n-- Key / value platform settings: 'pricing', 'reminders', 'whatsapp', …\n-- 'reminders' = {enabled, daysBefore, supportContact, lastRunOn} — the daily Cron skips when lastRunOn = today,\n-- so a re-run never sends twice. Reminder history = whatsapp_messages (kind 'renewal_reminder').\nCREATE TABLE IF NOT EXISTS \"platform_settings\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"setting_key\"              TEXT     NOT NULL UNIQUE,  -- max 60\n  \"value_json\"               TEXT     NOT NULL,\n  \"schema_version\"           INTEGER  NOT NULL DEFAULT 1,\n  \"updated_by\"               INTEGER  REFERENCES \"platform_admins\"(\"id\") ON DELETE SET NULL,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"platform_settings_updated_at\" AFTER UPDATE ON \"platform_settings\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"platform_settings\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_platform_settings_updated_by\" ON \"platform_settings\" (\"updated_by\");\n\nCREATE TABLE IF NOT EXISTS \"feature_flags\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"feature_key\"              TEXT     NOT NULL UNIQUE,  -- max 40 · whatsapp | …\n  \"name\"                     TEXT     NOT NULL,  -- max 80\n  \"rollout\"                  INTEGER  NOT NULL DEFAULT 1 CHECK (\"rollout\" >= 1),  -- Rollout: 1 off, 2 selected, 3 all\n  \"description\"              TEXT,  -- max 255\n  \"updated_by\"               INTEGER  REFERENCES \"platform_admins\"(\"id\") ON DELETE SET NULL,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"feature_flags_updated_at\" AFTER UPDATE ON \"feature_flags\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"feature_flags\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_feature_flags_updated_by\" ON \"feature_flags\" (\"updated_by\");\n\nCREATE TABLE IF NOT EXISTS \"businesses\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"name\"                     TEXT     NOT NULL,  -- max 150\n  \"category\"                 INTEGER  NOT NULL CHECK (\"category\" >= 1),  -- BusinessCategory: 1 retail, 2 food, 3 restaurant, 4 service\n  \"sub_type\"                 TEXT     NOT NULL,  -- max 60 · Supermarket | Hardware | Fast Food | Bakery | … (picks terminology & defaults)\n  \"phone\"                    TEXT,  -- max 16 · E.164\n  \"email\"                    TEXT,  -- max 150\n  \"address\"                  TEXT,  -- max 255\n  \"city\"                     TEXT,  -- max 80\n  \"state\"                    TEXT,  -- max 80\n  \"country_code\"             TEXT     NOT NULL DEFAULT 'IN',  -- max 2 · ISO 3166\n  \"currency_code\"            TEXT     NOT NULL DEFAULT 'INR',  -- max 3 · ISO 4217\n  \"currency_symbol\"          TEXT     NOT NULL DEFAULT '₹',  -- max 5\n  \"timezone\"                 TEXT     NOT NULL DEFAULT 'Asia/Kolkata',  -- max 40\n  \"gstin\"                    TEXT,  -- max 15\n  \"logo_media_id\"            INTEGER,  -- → media_files.ROWID (no FK: media_files refers back here). NULL = the app shows the default icon for category / sub_type; no emoji column.\n  \"status\"                   INTEGER  NOT NULL DEFAULT 1 CHECK (\"status\" >= 1),  -- BusinessStatus: 1 active, 2 deactivated\n  \"plan_id\"                  INTEGER  REFERENCES \"plans\"(\"id\") ON DELETE SET NULL,\n  \"max_branches\"             INTEGER  NOT NULL DEFAULT 1,\n  \"subscription_start_at\"    TEXT,\n  \"subscription_end_at\"      TEXT,  -- after this: read-only\n  \"reminders_paused\"         INTEGER  NOT NULL DEFAULT 0 CHECK (\"reminders_paused\" IN (0, 1)),\n  \"admin_note\"               TEXT,  -- max 255 · product admin only, never shown to the customer\n  \"onboarded_at\"             TEXT,\n  \"deleted_at\"               TEXT,  -- set when the admin deletes the customer (download the export first) Directory for the product admin's customer list (copies kept up to date by the API, so the list never has to open every shop's own database):\n  \"owner_user_id\"            INTEGER,  -- → users.ROWID of the owner login (in the shop's database)\n  \"owner_name\"               TEXT,  -- max 120\n  \"owner_username\"           TEXT,  -- max 40\n  \"owner_phone\"              TEXT,  -- max 16 · E.164, the owner's sign-in mobile (renewal reminders go here)\n  \"owner_email\"              TEXT,  -- max 150\n  \"branches_used\"            INTEGER  NOT NULL DEFAULT 1,\n  \"last_login_at\"            TEXT,  -- newest sign-in of any user of this shop\n  \"last_activity_at\"         TEXT,  -- newest change (updated at most once an hour)\n  \"row_version\"              INTEGER  NOT NULL DEFAULT 1,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"businesses_updated_at\" AFTER UPDATE ON \"businesses\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"businesses\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_businesses_plan_id\" ON \"businesses\" (\"plan_id\");\n\n-- Secrets (WhatsApp tokens etc.) — the only place they are kept. Never returned to a browser.\nCREATE TABLE IF NOT EXISTS \"secrets\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"owner_type\"               INTEGER  NOT NULL CHECK (\"owner_type\" >= 1),  -- SecretOwner: 1 platform, 2 business\n  \"business_id\"              INTEGER  REFERENCES \"businesses\"(\"id\") ON DELETE CASCADE,  -- NULL for platform secrets\n  \"kind\"                     INTEGER  NOT NULL CHECK (\"kind\" >= 1),  -- SecretKind: 1 whatsapp_token\n  \"value\"                    TEXT     NOT NULL,  -- AES-256-GCM ciphertext (encrypted in the API)\n  \"last4\"                    TEXT,  -- max 4\n  \"uniq_key\"                 TEXT     NOT NULL UNIQUE,  -- max 120 · '<owner_type>:<business_id|0>:<kind>'\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"secrets_updated_at\" AFTER UPDATE ON \"secrets\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"secrets\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_secrets_business_id\" ON \"secrets\" (\"business_id\");\n\nCREATE TABLE IF NOT EXISTS \"subscription_periods\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL REFERENCES \"businesses\"(\"id\") ON DELETE CASCADE,\n  \"kind\"                     INTEGER  NOT NULL CHECK (\"kind\" >= 1),  -- PeriodKind: 1 new, 2 renew, 3 extend, 4 change\n  \"start_at\"                 TEXT     NOT NULL,\n  \"end_at\"                   TEXT     NOT NULL,\n  \"months\"                   INTEGER,  -- NULL for custom dates\n  \"branches\"                 INTEGER  NOT NULL,\n  \"price_per_branch_minor\"   INTEGER  NOT NULL,  -- rate used (prices can change later)\n  \"amount_minor\"             INTEGER  NOT NULL,\n  \"payment_ref\"              TEXT,  -- max 80\n  \"note\"                     TEXT,  -- max 255\n  \"admin_id\"                 INTEGER  REFERENCES \"platform_admins\"(\"id\") ON DELETE SET NULL,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"subscription_periods_updated_at\" AFTER UPDATE ON \"subscription_periods\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"subscription_periods\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_subscription_periods_business_id_created_at\" ON \"subscription_periods\" (\"business_id\", \"created_at\");\nCREATE INDEX IF NOT EXISTS \"ix_subscription_periods_admin_id\" ON \"subscription_periods\" (\"admin_id\");\n\n-- Features released to selected customers (feature_flags.rollout = 'selected').\nCREATE TABLE IF NOT EXISTS \"feature_flag_businesses\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"feature_flag_id\"          INTEGER  NOT NULL REFERENCES \"feature_flags\"(\"id\") ON DELETE CASCADE,\n  \"business_id\"              INTEGER  NOT NULL REFERENCES \"businesses\"(\"id\") ON DELETE CASCADE,\n  \"uniq_key\"                 TEXT     NOT NULL UNIQUE,  -- max 60 · '<feature_flag_id>:<business_id>'\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"feature_flag_businesses_updated_at\" AFTER UPDATE ON \"feature_flag_businesses\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"feature_flag_businesses\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_feature_flag_businesses_feature_flag_id\" ON \"feature_flag_businesses\" (\"feature_flag_id\");\nCREATE INDEX IF NOT EXISTS \"ix_feature_flag_businesses_business_id\" ON \"feature_flag_businesses\" (\"business_id\");\n\n-- Message templates — the customer's (business_id set) and the platform's (business_id NULL).\nCREATE TABLE IF NOT EXISTS \"whatsapp_templates\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  REFERENCES \"businesses\"(\"id\") ON DELETE CASCADE,\n  \"kind\"                     INTEGER  NOT NULL CHECK (\"kind\" >= 1),  -- WaTemplateKind: 1 bill, 2 offer, 3 renewal_reminder\n  \"language\"                 TEXT     NOT NULL,  -- max 5 · en | ta\n  \"body\"                     TEXT     NOT NULL,\n  \"attach\"                   INTEGER  NOT NULL DEFAULT 0 CHECK (\"attach\" IN (0, 1)),  -- PDF / poster header\n  \"meta_template_name\"       TEXT,  -- max 80\n  \"status\"                   INTEGER  NOT NULL DEFAULT 1 CHECK (\"status\" >= 1),  -- WaTemplateStatus: 1 draft, 2 pending, 3 approved, 4 rejected\n  \"reject_reason\"            TEXT,  -- max 255\n  \"submitted_at\"             TEXT,\n  \"approved_at\"              TEXT,\n  \"uniq_key\"                 TEXT     NOT NULL UNIQUE,  -- max 60 · '<business_id|platform>:<kind>'\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"whatsapp_templates_updated_at\" AFTER UPDATE ON \"whatsapp_templates\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"whatsapp_templates\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_whatsapp_templates_business_id\" ON \"whatsapp_templates\" (\"business_id\");\n\n-- What the product admin team did.\nCREATE TABLE IF NOT EXISTS \"admin_audit_logs\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"admin_id\"                 INTEGER  REFERENCES \"platform_admins\"(\"id\") ON DELETE SET NULL,\n  \"admin_name\"               TEXT     NOT NULL,  -- max 120 · snapshot\n  \"business_id\"              INTEGER  REFERENCES \"businesses\"(\"id\") ON DELETE SET NULL,  -- NULL after the customer is deleted\n  \"business_name\"            TEXT,  -- max 150 · snapshot (kept after delete)\n  \"action\"                   INTEGER  NOT NULL CHECK (\"action\" >= 1),  -- AdminAction: 1 create, 2 update, 3 password, 4 renew, 5 branch_limit, 6 activate, 7 deactivate, 8 delete, 9 settings, 10 login, 11 export, 12 reminder, 13 support_start, 14 support_end, 15 admin_create, 16 admin_update, 17 feature\n  \"detail\"                   TEXT,  -- max 255\n  \"ip\"                       TEXT,  -- max 45\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"admin_audit_logs_updated_at\" AFTER UPDATE ON \"admin_audit_logs\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"admin_audit_logs\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_admin_audit_logs_business_id_created_at\" ON \"admin_audit_logs\" (\"business_id\", \"created_at\");\nCREATE INDEX IF NOT EXISTS \"ix_admin_audit_logs_created_at\" ON \"admin_audit_logs\" (\"created_at\");\nCREATE INDEX IF NOT EXISTS \"ix_admin_audit_logs_admin_id\" ON \"admin_audit_logs\" (\"admin_id\");\n\n-- Sign-in names → which shop they belong to. Usernames, mobile numbers and emails are unique across every\n-- shop and admin, and with one database per shop this is how sign-in finds the right one.\nCREATE TABLE IF NOT EXISTS \"login_names\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"login\"                    TEXT     NOT NULL UNIQUE,  -- max 160 · lower-case username, E.164 mobile or lower-case email\n  \"kind\"                     INTEGER  NOT NULL CHECK (\"kind\" >= 1),  -- LoginKind: 1 username, 2 phone, 3 email\n  \"business_id\"              INTEGER  NOT NULL REFERENCES \"businesses\"(\"id\") ON DELETE CASCADE,\n  \"user_id\"                  INTEGER  NOT NULL,  -- → users.ROWID in the shop's database\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"login_names_updated_at\" AFTER UPDATE ON \"login_names\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"login_names\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_login_names_business_id\" ON \"login_names\" (\"business_id\");\n\n-- Where each shop's own database is (Turso: one database per shop). Not used when everything is in one database.\nCREATE TABLE IF NOT EXISTS \"shop_databases\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL UNIQUE REFERENCES \"businesses\"(\"id\") ON DELETE CASCADE,\n  \"db_name\"                  TEXT     NOT NULL UNIQUE,  -- max 64\n  \"db_url\"                   TEXT,  -- max 255\n  \"schema_version\"           TEXT,  -- max 40 · newest migration applied\n  \"status\"                   INTEGER  NOT NULL DEFAULT 1 CHECK (\"status\" >= 1),  -- ShopDbStatus: 1 creating, 2 ready, 3 failed, 4 deleting\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"shop_databases_updated_at\" AFTER UPDATE ON \"shop_databases\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"shop_databases\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\n\n-- Images and files stored in Stratus.\nCREATE TABLE IF NOT EXISTS \"media_files\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  REFERENCES \"businesses\"(\"id\") ON DELETE CASCADE,  -- NULL = platform file\n  \"purpose\"                  INTEGER  NOT NULL CHECK (\"purpose\" >= 1),  -- MediaPurpose: 1 product, 2 category, 3 logo, 4 ticket, 5 poster\n  \"bucket\"                   TEXT     NOT NULL,  -- max 60\n  \"object_key\"               TEXT     NOT NULL UNIQUE,  -- max 255 · '<business_id>/products/<uuid>.webp'\n  \"thumb_key\"                TEXT,  -- max 255\n  \"content_type\"             TEXT     NOT NULL,  -- max 40 · image/webp | application/zip | …\n  \"bytes\"                    INTEGER  NOT NULL,  -- photos ≤ 51,200\n  \"width\"                    INTEGER,\n  \"height\"                   INTEGER,\n  \"original_bytes\"           INTEGER,\n  \"created_by\"               INTEGER,  -- → users.id in the shop database (checked by the API)\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"media_files_updated_at\" AFTER UPDATE ON \"media_files\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"media_files\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_media_files_business_id\" ON \"media_files\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_media_files_created_by\" ON \"media_files\" (\"created_by\");\n\nCREATE TABLE IF NOT EXISTS \"support_tickets\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL REFERENCES \"businesses\"(\"id\") ON DELETE CASCADE,\n  \"user_id\"                  INTEGER,  -- → users.id in the shop database (checked by the API)\n  \"number\"                   TEXT     NOT NULL UNIQUE,  -- max 20 · T-1001\n  \"subject\"                  TEXT     NOT NULL,  -- max 120\n  \"category\"                 INTEGER  NOT NULL CHECK (\"category\" >= 1),  -- TicketCategory: 1 billing, 2 printer, 3 stock, 4 whatsapp, 5 account, 6 other\n  \"priority\"                 INTEGER  NOT NULL DEFAULT 2 CHECK (\"priority\" >= 1),  -- TicketPriority: 1 low, 2 normal, 3 high, 4 urgent\n  \"status\"                   INTEGER  NOT NULL DEFAULT 1 CHECK (\"status\" >= 1),  -- TicketStatus: 1 open, 2 in_progress, 3 waiting, 4 resolved, 5 closed\n  \"assigned_to\"              INTEGER  REFERENCES \"platform_admins\"(\"id\") ON DELETE SET NULL,\n  \"page\"                     TEXT,  -- max 200\n  \"browser\"                  TEXT,  -- max 255\n  \"app_version\"              TEXT,  -- max 20\n  \"device_id\"                INTEGER,  -- → devices.id in the shop database (checked by the API)\n  \"user_name\"                TEXT,  -- max 120 · snapshot of who raised it (the admin inbox reads no shop data)\n  \"user_phone\"               TEXT,  -- max 16\n  \"unread_for_admin\"         INTEGER  NOT NULL DEFAULT 1 CHECK (\"unread_for_admin\" IN (0, 1)),\n  \"unread_for_customer\"      INTEGER  NOT NULL DEFAULT 0 CHECK (\"unread_for_customer\" IN (0, 1)),\n  \"last_message_at\"          TEXT     NOT NULL,\n  \"resolved_at\"              TEXT,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"support_tickets_updated_at\" AFTER UPDATE ON \"support_tickets\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"support_tickets\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_support_tickets_business_id_last_message_at\" ON \"support_tickets\" (\"business_id\", \"last_message_at\");\nCREATE INDEX IF NOT EXISTS \"ix_support_tickets_status_last_message_at\" ON \"support_tickets\" (\"status\", \"last_message_at\");\nCREATE INDEX IF NOT EXISTS \"ix_support_tickets_user_id\" ON \"support_tickets\" (\"user_id\");\nCREATE INDEX IF NOT EXISTS \"ix_support_tickets_assigned_to\" ON \"support_tickets\" (\"assigned_to\");\nCREATE INDEX IF NOT EXISTS \"ix_support_tickets_device_id\" ON \"support_tickets\" (\"device_id\");\n\nCREATE TABLE IF NOT EXISTS \"ticket_messages\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"ticket_id\"                INTEGER  NOT NULL REFERENCES \"support_tickets\"(\"id\") ON DELETE CASCADE,\n  \"from_side\"                INTEGER  NOT NULL CHECK (\"from_side\" >= 1),  -- TicketSide: 1 customer, 2 admin\n  \"user_id\"                  INTEGER,  -- → users.id in the shop database (checked by the API)\n  \"admin_id\"                 INTEGER  REFERENCES \"platform_admins\"(\"id\") ON DELETE SET NULL,\n  \"author_name\"              TEXT     NOT NULL,  -- max 120\n  \"body\"                     TEXT,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"ticket_messages_updated_at\" AFTER UPDATE ON \"ticket_messages\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"ticket_messages\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_ticket_messages_ticket_id_created_at\" ON \"ticket_messages\" (\"ticket_id\", \"created_at\");\nCREATE INDEX IF NOT EXISTS \"ix_ticket_messages_user_id\" ON \"ticket_messages\" (\"user_id\");\nCREATE INDEX IF NOT EXISTS \"ix_ticket_messages_admin_id\" ON \"ticket_messages\" (\"admin_id\");\n\n-- Every WhatsApp message: bills, offers, tests, and platform renewal reminders (business_id = customer).\nCREATE TABLE IF NOT EXISTS \"whatsapp_messages\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  REFERENCES \"businesses\"(\"id\") ON DELETE CASCADE,\n  \"sender\"                   INTEGER  NOT NULL CHECK (\"sender\" >= 1),  -- WaSender: 1 business, 2 platform\n  \"kind\"                     INTEGER  NOT NULL CHECK (\"kind\" >= 1),  -- WaMessageKind: 1 bill, 2 offer, 3 test, 4 renewal_reminder\n  \"to_number\"                TEXT     NOT NULL,  -- max 16\n  \"customer_id\"              INTEGER,  -- → customers.id in the shop database (checked by the API)\n  \"order_id\"                 INTEGER,  -- → orders.id in the shop database (checked by the API)\n  \"campaign_id\"              INTEGER,  -- → campaigns.id in the shop database (checked by the API)\n  \"template_id\"              INTEGER  REFERENCES \"whatsapp_templates\"(\"id\") ON DELETE SET NULL,\n  \"body\"                     TEXT     NOT NULL,\n  \"attachment_media_id\"      INTEGER  REFERENCES \"media_files\"(\"id\") ON DELETE SET NULL,\n  \"meta_message_id\"          TEXT     UNIQUE,  -- max 80 · updated by Meta's webhook\n  \"status\"                   INTEGER  NOT NULL DEFAULT 1 CHECK (\"status\" >= 1),  -- WaMessageStatus: 1 queued, 2 sent, 3 delivered, 4 read, 5 failed\n  \"error\"                    TEXT,  -- max 255\n  \"status_at\"                TEXT,\n  \"created_by\"               INTEGER,  -- → users.id in the shop database (checked by the API)\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"whatsapp_messages_updated_at\" AFTER UPDATE ON \"whatsapp_messages\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"whatsapp_messages\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_whatsapp_messages_business_id_created_at\" ON \"whatsapp_messages\" (\"business_id\", \"created_at\");\nCREATE INDEX IF NOT EXISTS \"ix_whatsapp_messages_campaign_id\" ON \"whatsapp_messages\" (\"campaign_id\");\nCREATE INDEX IF NOT EXISTS \"ix_whatsapp_messages_customer_id\" ON \"whatsapp_messages\" (\"customer_id\");\nCREATE INDEX IF NOT EXISTS \"ix_whatsapp_messages_order_id\" ON \"whatsapp_messages\" (\"order_id\");\nCREATE INDEX IF NOT EXISTS \"ix_whatsapp_messages_template_id\" ON \"whatsapp_messages\" (\"template_id\");\nCREATE INDEX IF NOT EXISTS \"ix_whatsapp_messages_attachment_media_id\" ON \"whatsapp_messages\" (\"attachment_media_id\");\nCREATE INDEX IF NOT EXISTS \"ix_whatsapp_messages_created_by\" ON \"whatsapp_messages\" (\"created_by\");\n\nCREATE TABLE IF NOT EXISTS \"ticket_attachments\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"message_id\"               INTEGER  NOT NULL REFERENCES \"ticket_messages\"(\"id\") ON DELETE CASCADE,\n  \"media_id\"                 INTEGER  NOT NULL REFERENCES \"media_files\"(\"id\") ON DELETE CASCADE,  -- screenshots ≤ 1600 px / 200 KB, up to 5\n  \"sort_order\"               INTEGER  NOT NULL DEFAULT 0,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"ticket_attachments_updated_at\" AFTER UPDATE ON \"ticket_attachments\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"ticket_attachments\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_ticket_attachments_message_id\" ON \"ticket_attachments\" (\"message_id\");\nCREATE INDEX IF NOT EXISTS \"ix_ticket_attachments_media_id\" ON \"ticket_attachments\" (\"media_id\");\n\n-- =====================================================================================================\n--  Added for Turso\n-- =====================================================================================================\n\n-- Which migration files have run on this database.\nCREATE TABLE IF NOT EXISTS \"schema_migrations\" (\n  \"version\"                  TEXT     PRIMARY KEY,  -- file name, e.g. 0001_init\n  \"applied_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))\n) STRICT;\n"}],"shop":[{"version":"0001_init","sql":"-- =====================================================================================================\n--  BillPoodum — Turso (libSQL / SQLite) schema: shop database (one per shop)\n-- =====================================================================================================\n--  GENERATED by backend/scripts/gen-sqlite.mjs from server/catalyst/schema.sql — do not edit by hand.\n--  To change a table: edit schema.sql, run the generator, and add the difference as a new migration file\n--  backend/migrations/shop/NNNN_<what>.sql (ALTER TABLE …). The tests check the migrations add up to this file.\n--\n--  Same tables, columns and relations as the approved design (see server/catalyst/TABLES.md). Mapping:\n--    Catalyst ROWID              → \"id\" INTEGER PRIMARY KEY AUTOINCREMENT (never reused; the API calls it ROWID)\n--    CREATEDTIME / MODIFIEDTIME  → \"created_at\" / \"updated_at\"  TEXT, ISO-8601 UTC (set automatically)\n--    VARCHAR(n) / TEXT           → TEXT  (max length checked by the API, so it can grow without a table rebuild)\n--    INT / BIGINT / FK ids       → INTEGER   · money in paise, qty in thousandths, % in basis points\n--    BOOLEAN                     → INTEGER 0 / 1\n--    DATE / DATETIME             → TEXT  YYYY-MM-DD / ISO-8601 UTC (sorts and compares correctly)\n--    ENCRYPTED                   → TEXT holding AES-256-GCM ciphertext (the API encrypts with SECRETS_KEY)\n--    Fixed lists (enums)         → INTEGER codes from server/catalyst/enums.ts (CHECK >= 1 only, so a new\n--                                   value never needs a migration). Never renumber; add at the end.\n--    FK → x CASCADE / NULL       → REFERENCES x(\"id\") ON DELETE CASCADE / SET NULL — only when x is in this\n--                                   database; a reference to the other database is a plain INTEGER.\n--  The API turns on foreign keys (\"PRAGMA foreign_keys = ON\") on every connection.\n-- =====================================================================================================\n\n-- Secrets (WhatsApp tokens etc.) — the only place they are kept. Never returned to a browser.\nCREATE TABLE IF NOT EXISTS \"secrets\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"owner_type\"               INTEGER  NOT NULL CHECK (\"owner_type\" >= 1),  -- SecretOwner: 1 platform, 2 business\n  \"business_id\"              INTEGER,  -- → businesses.id in the platform database (checked by the API) · NULL for platform secrets\n  \"kind\"                     INTEGER  NOT NULL CHECK (\"kind\" >= 1),  -- SecretKind: 1 whatsapp_token\n  \"value\"                    TEXT     NOT NULL,  -- AES-256-GCM ciphertext (encrypted in the API)\n  \"last4\"                    TEXT,  -- max 4\n  \"uniq_key\"                 TEXT     NOT NULL UNIQUE,  -- max 120 · '<owner_type>:<business_id|0>:<kind>'\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"secrets_updated_at\" AFTER UPDATE ON \"secrets\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"secrets\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_secrets_business_id\" ON \"secrets\" (\"business_id\");\n\nCREATE TABLE IF NOT EXISTS \"branches\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"name\"                     TEXT     NOT NULL,  -- max 120\n  \"code\"                     TEXT,  -- max 10 · short code, e.g. ADY\n  \"address\"                  TEXT,  -- max 255\n  \"phone\"                    TEXT,  -- max 16\n  \"gstin\"                    TEXT,  -- max 15 · a branch in another state has its own GSTIN\n  \"is_default\"               INTEGER  NOT NULL DEFAULT 0 CHECK (\"is_default\" IN (0, 1)),\n  \"is_active\"                INTEGER  NOT NULL DEFAULT 1 CHECK (\"is_active\" IN (0, 1)),\n  \"invoice_prefix\"           TEXT,  -- max 10 · own bill series, e.g. 'AD-'; NULL = business series\n  \"printer_json\"             TEXT,  -- receipt printer setup: {transport, paper, mode, autoPrint, copies, cut, drawer, baudRate}\n  \"row_version\"              INTEGER  NOT NULL DEFAULT 1,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"branches_updated_at\" AFTER UPDATE ON \"branches\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"branches\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_branches_business_id\" ON \"branches\" (\"business_id\");\n\nCREATE TABLE IF NOT EXISTS \"roles\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"name\"                     TEXT     NOT NULL,  -- max 60 · Owner | Manager | Cashier | Waiter | Kitchen | custom\n  \"system_key\"               INTEGER  CHECK (\"system_key\" IS NULL OR \"system_key\" >= 1),  -- RoleKey: 1 owner, 2 manager, 3 cashier, 4 waiter, 5 kitchen; NULL = custom role\n  \"is_all_access\"            INTEGER  NOT NULL DEFAULT 0 CHECK (\"is_all_access\" IN (0, 1)),  -- owner\n  \"uniq_key\"                 TEXT     NOT NULL UNIQUE,  -- max 100 · '<business_id>:<lower(name)>'\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"roles_updated_at\" AFTER UPDATE ON \"roles\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"roles\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_roles_business_id\" ON \"roles\" (\"business_id\");\n\nCREATE TABLE IF NOT EXISTS \"tax_rates\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"name\"                     TEXT     NOT NULL,  -- max 40 · 'GST 5%'\n  \"rate_bp\"                  INTEGER  NOT NULL,  -- 500\n  \"is_inclusive\"             INTEGER  NOT NULL DEFAULT 0 CHECK (\"is_inclusive\" IN (0, 1)),  -- prices include tax\n  \"is_default\"               INTEGER  NOT NULL DEFAULT 0 CHECK (\"is_default\" IN (0, 1)),\n  \"is_active\"                INTEGER  NOT NULL DEFAULT 1 CHECK (\"is_active\" IN (0, 1)),\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"tax_rates_updated_at\" AFTER UPDATE ON \"tax_rates\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"tax_rates\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_tax_rates_business_id\" ON \"tax_rates\" (\"business_id\");\n\n-- Price lists: Retail (default) + any number of others (Contractor, Wholesale, Dealer…).\nCREATE TABLE IF NOT EXISTS \"price_lists\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"name\"                     TEXT     NOT NULL,  -- max 60 · 'Contractor rate'\n  \"is_default\"               INTEGER  NOT NULL DEFAULT 0 CHECK (\"is_default\" IN (0, 1)),  -- retail = products.price_minor\n  \"is_active\"                INTEGER  NOT NULL DEFAULT 1 CHECK (\"is_active\" IN (0, 1)),\n  \"uniq_key\"                 TEXT     NOT NULL UNIQUE,  -- max 100 · '<business_id>:<lower(name)>'\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"price_lists_updated_at\" AFTER UPDATE ON \"price_lists\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"price_lists\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_price_lists_business_id\" ON \"price_lists\" (\"business_id\");\n\nCREATE TABLE IF NOT EXISTS \"suppliers\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"name\"                     TEXT     NOT NULL,  -- max 150\n  \"phone\"                    TEXT,  -- max 16\n  \"gstin\"                    TEXT,  -- max 15\n  \"address\"                  TEXT,  -- max 255\n  \"is_active\"                INTEGER  NOT NULL DEFAULT 1 CHECK (\"is_active\" IN (0, 1)),\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"suppliers_updated_at\" AFTER UPDATE ON \"suppliers\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"suppliers\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_suppliers_business_id\" ON \"suppliers\" (\"business_id\");\n\nCREATE TABLE IF NOT EXISTS \"expense_categories\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"name\"                     TEXT     NOT NULL,  -- max 60 · Purchase | Salary | Rent | Electricity | Transport | Maintenance | Other | custom\n  \"system_key\"               INTEGER  CHECK (\"system_key\" IS NULL OR \"system_key\" >= 1),  -- ExpenseKey: 1 purchase, 2 salary, 3 rent, 4 electricity, 5 transport, 6 maintenance, 7 other\n  \"is_active\"                INTEGER  NOT NULL DEFAULT 1 CHECK (\"is_active\" IN (0, 1)),\n  \"uniq_key\"                 TEXT     NOT NULL UNIQUE,  -- max 100 · '<business_id>:<lower(name)>'\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"expense_categories_updated_at\" AFTER UPDATE ON \"expense_categories\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"expense_categories\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_expense_categories_business_id\" ON \"expense_categories\" (\"business_id\");\n\n-- Message templates — the customer's (business_id set) and the platform's (business_id NULL).\nCREATE TABLE IF NOT EXISTS \"whatsapp_templates\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER,  -- → businesses.id in the platform database (checked by the API)\n  \"kind\"                     INTEGER  NOT NULL CHECK (\"kind\" >= 1),  -- WaTemplateKind: 1 bill, 2 offer, 3 renewal_reminder\n  \"language\"                 TEXT     NOT NULL,  -- max 5 · en | ta\n  \"body\"                     TEXT     NOT NULL,\n  \"attach\"                   INTEGER  NOT NULL DEFAULT 0 CHECK (\"attach\" IN (0, 1)),  -- PDF / poster header\n  \"meta_template_name\"       TEXT,  -- max 80\n  \"status\"                   INTEGER  NOT NULL DEFAULT 1 CHECK (\"status\" >= 1),  -- WaTemplateStatus: 1 draft, 2 pending, 3 approved, 4 rejected\n  \"reject_reason\"            TEXT,  -- max 255\n  \"submitted_at\"             TEXT,\n  \"approved_at\"              TEXT,\n  \"uniq_key\"                 TEXT     NOT NULL UNIQUE,  -- max 60 · '<business_id|platform>:<kind>'\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"whatsapp_templates_updated_at\" AFTER UPDATE ON \"whatsapp_templates\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"whatsapp_templates\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_whatsapp_templates_business_id\" ON \"whatsapp_templates\" (\"business_id\");\n\n-- Number series (bill, order, KOT, credit note, ticket …). Read-and-increment with row_version check.\nCREATE TABLE IF NOT EXISTS \"sequences\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"branch_id\"                INTEGER  REFERENCES \"branches\"(\"id\") ON DELETE CASCADE,  -- NULL = business-wide series\n  \"name\"                     INTEGER  NOT NULL CHECK (\"name\" >= 1),  -- SequenceName: 1 invoice, 2 order, 3 kot, 4 credit_note, 5 purchase\n  \"prefix\"                   TEXT     NOT NULL DEFAULT '',  -- max 20\n  \"next_value\"               INTEGER  NOT NULL DEFAULT 1,\n  \"fiscal_year\"              TEXT,  -- max 9 · '2026-27' when the series restarts every April\n  \"uniq_key\"                 TEXT     NOT NULL UNIQUE,  -- max 80 · '<business_id>:<branch_id|0>:<name>:<fiscal_year|->'\n  \"row_version\"              INTEGER  NOT NULL DEFAULT 1,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"sequences_updated_at\" AFTER UPDATE ON \"sequences\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"sequences\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_sequences_business_id\" ON \"sequences\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_sequences_branch_id\" ON \"sequences\" (\"branch_id\");\n\n-- POS devices (counters, waiter phones, kitchen screens). For offline sync.\nCREATE TABLE IF NOT EXISTS \"devices\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"branch_id\"                INTEGER  NOT NULL REFERENCES \"branches\"(\"id\") ON DELETE CASCADE,\n  \"name\"                     TEXT     NOT NULL,  -- max 80 · 'Counter 1'\n  \"kind\"                     INTEGER  NOT NULL CHECK (\"kind\" >= 1),  -- DeviceKind: 1 counter, 2 waiter, 3 kitchen, 4 display\n  \"device_uuid\"              TEXT     NOT NULL UNIQUE,  -- max 40\n  \"platform\"                 INTEGER  CHECK (\"platform\" IS NULL OR \"platform\" >= 1),  -- DevicePlatform: 1 web, 2 android, 3 ios\n  \"app_version\"              TEXT,  -- max 20\n  \"last_seen_at\"             TEXT,\n  \"last_sync_at\"             TEXT,\n  \"is_active\"                INTEGER  NOT NULL DEFAULT 1 CHECK (\"is_active\" IN (0, 1)),\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"devices_updated_at\" AFTER UPDATE ON \"devices\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"devices\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_devices_business_id\" ON \"devices\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_devices_branch_id\" ON \"devices\" (\"branch_id\");\n\nCREATE TABLE IF NOT EXISTS \"role_permissions\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"role_id\"                  INTEGER  NOT NULL REFERENCES \"roles\"(\"id\") ON DELETE CASCADE,\n  \"permission\"               TEXT     NOT NULL,  -- max 40 · billing.create | orders.cancel | reports.profit | …\n  \"uniq_key\"                 TEXT     NOT NULL UNIQUE,  -- max 80 · '<role_id>:<permission>'\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"role_permissions_updated_at\" AFTER UPDATE ON \"role_permissions\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"role_permissions\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_role_permissions_role_id\" ON \"role_permissions\" (\"role_id\");\n\nCREATE TABLE IF NOT EXISTS \"users\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"role_id\"                  INTEGER  REFERENCES \"roles\"(\"id\") ON DELETE SET NULL,\n  \"default_branch_id\"        INTEGER  REFERENCES \"branches\"(\"id\") ON DELETE SET NULL,\n  \"name\"                     TEXT     NOT NULL,  -- max 120\n  \"phone\"                    TEXT     NOT NULL UNIQUE,  -- max 16 · E.164, sign-in ID\n  \"email\"                    TEXT,  -- max 150\n  \"username\"                 TEXT     UNIQUE,  -- max 40 · owner login created by the product admin\n  \"catalyst_user_id\"         INTEGER  UNIQUE,  -- only if Catalyst Authentication is used later\n  \"password_hash\"            TEXT,  -- max 100 · bcrypt of the password the admin gives; never plain text\n  \"must_change_password\"     INTEGER  NOT NULL DEFAULT 1 CHECK (\"must_change_password\" IN (0, 1)),  -- ask for a new password on first sign-in\n  \"password_changed_at\"      TEXT,\n  \"failed_logins\"            INTEGER  NOT NULL DEFAULT 0,  -- lock for 15 min after 5 wrong tries\n  \"locked_until\"             TEXT,\n  \"token_version\"            INTEGER  NOT NULL DEFAULT 1,  -- in the sign-in token; +1 on password reset / turn off → old sessions end\n  \"language\"                 TEXT     NOT NULL DEFAULT 'en',  -- max 5 · en | ta | …\n  \"pin_hash\"                 TEXT,  -- max 100 · optional quick PIN for shared counters (bcrypt) staff pay\n  \"pay_type\"                 INTEGER  CHECK (\"pay_type\" IS NULL OR \"pay_type\" >= 1),  -- PayType: 1 monthly, 2 daily; NULL = not on payroll\n  \"pay_amount_minor\"         INTEGER  NOT NULL DEFAULT 0,\n  \"commission_bp\"            INTEGER  NOT NULL DEFAULT 0,  -- % of own net sales\n  \"joined_on\"                TEXT     CHECK (\"joined_on\" IS NULL OR \"joined_on\" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),\n  \"is_active\"                INTEGER  NOT NULL DEFAULT 1 CHECK (\"is_active\" IN (0, 1)),\n  \"last_login_at\"            TEXT,\n  \"row_version\"              INTEGER  NOT NULL DEFAULT 1,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"users_updated_at\" AFTER UPDATE ON \"users\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"users\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_users_business_id_is_active\" ON \"users\" (\"business_id\", \"is_active\");\nCREATE INDEX IF NOT EXISTS \"ix_users_role_id\" ON \"users\" (\"role_id\");\nCREATE INDEX IF NOT EXISTS \"ix_users_default_branch_id\" ON \"users\" (\"default_branch_id\");\n\nCREATE TABLE IF NOT EXISTS \"customers\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"name\"                     TEXT     NOT NULL,  -- max 120\n  \"phone\"                    TEXT,  -- max 16 · E.164\n  \"phone_key\"                TEXT     UNIQUE,  -- max 60 · '<business_id>:<phone>' (NULL when no phone)\n  \"email\"                    TEXT,  -- max 150\n  \"address\"                  TEXT,  -- max 255\n  \"gstin\"                    TEXT,  -- max 15 · B2B bills\n  \"price_list_id\"            INTEGER  REFERENCES \"price_lists\"(\"id\") ON DELETE SET NULL,  -- NULL = retail\n  \"credit_limit_minor\"       INTEGER,\n  \"marketing_opt_in\"         INTEGER  NOT NULL DEFAULT 1 CHECK (\"marketing_opt_in\" IN (0, 1)),\n  \"notes\"                    TEXT,  -- max 255\n  \"is_active\"                INTEGER  NOT NULL DEFAULT 1 CHECK (\"is_active\" IN (0, 1)),\n  \"row_version\"              INTEGER  NOT NULL DEFAULT 1,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"customers_updated_at\" AFTER UPDATE ON \"customers\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"customers\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_customers_business_id_is_active\" ON \"customers\" (\"business_id\", \"is_active\");\nCREATE INDEX IF NOT EXISTS \"ix_customers_price_list_id\" ON \"customers\" (\"price_list_id\");\n\nCREATE TABLE IF NOT EXISTS \"dining_tables\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"branch_id\"                INTEGER  NOT NULL REFERENCES \"branches\"(\"id\") ON DELETE CASCADE,\n  \"label\"                    TEXT     NOT NULL,  -- max 20 · T1, Patio 2\n  \"area\"                     TEXT,  -- max 40\n  \"seats\"                    INTEGER  NOT NULL DEFAULT 4,\n  \"qr_token\"                 TEXT     UNIQUE,  -- max 40 · QR menu link for this table\n  \"merged_into_id\"           INTEGER  REFERENCES \"dining_tables\"(\"id\") ON DELETE SET NULL,  -- tables merged for a big group → the main table\n  \"is_active\"                INTEGER  NOT NULL DEFAULT 1 CHECK (\"is_active\" IN (0, 1)),\n  \"uniq_key\"                 TEXT     NOT NULL UNIQUE,  -- max 80 · '<branch_id>:<lower(label)>'\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"dining_tables_updated_at\" AFTER UPDATE ON \"dining_tables\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"dining_tables\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_dining_tables_business_id\" ON \"dining_tables\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_dining_tables_branch_id\" ON \"dining_tables\" (\"branch_id\");\nCREATE INDEX IF NOT EXISTS \"ix_dining_tables_merged_into_id\" ON \"dining_tables\" (\"merged_into_id\");\n\nCREATE TABLE IF NOT EXISTS \"whatsapp_accounts\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL UNIQUE,  -- → businesses.id in the platform database (checked by the API) · one per business\n  \"provider\"                 INTEGER  NOT NULL DEFAULT 1 CHECK (\"provider\" >= 1),  -- WaProvider: 1 meta_cloud\n  \"business_number\"          TEXT,  -- max 16 · empty until the shop connects its account\n  \"waba_id\"                  TEXT,  -- max 25\n  \"phone_number_id\"          TEXT,  -- max 25\n  \"secret_id\"                INTEGER  REFERENCES \"secrets\"(\"id\") ON DELETE SET NULL,  -- access token\n  \"verified_name\"            TEXT,  -- max 120\n  \"quality\"                  INTEGER  CHECK (\"quality\" IS NULL OR \"quality\" >= 1),  -- WaQuality: 1 high, 2 medium, 3 low\n  \"verified_at\"              TEXT,\n  \"auto_send_bill\"           INTEGER  NOT NULL DEFAULT 0 CHECK (\"auto_send_bill\" IN (0, 1)),\n  \"setup_done_at\"            TEXT,\n  \"status\"                   INTEGER  NOT NULL DEFAULT 1 CHECK (\"status\" >= 1),  -- WaAccountStatus: 1 setup, 2 connected, 3 disconnected\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"whatsapp_accounts_updated_at\" AFTER UPDATE ON \"whatsapp_accounts\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"whatsapp_accounts\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_whatsapp_accounts_secret_id\" ON \"whatsapp_accounts\" (\"secret_id\");\n\n-- Key / value business settings: 'billing', 'terminology', 'modules', 'qr', 'wholesale', … (JSON each).\nCREATE TABLE IF NOT EXISTS \"business_settings\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"setting_key\"              TEXT     NOT NULL,  -- max 40\n  \"value_json\"               TEXT     NOT NULL,\n  \"schema_version\"           INTEGER  NOT NULL DEFAULT 1,\n  \"uniq_key\"                 TEXT     NOT NULL UNIQUE,  -- max 80 · '<business_id>:<setting_key>'\n  \"updated_by\"               INTEGER  REFERENCES \"users\"(\"id\") ON DELETE SET NULL,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"business_settings_updated_at\" AFTER UPDATE ON \"business_settings\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"business_settings\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_business_settings_business_id\" ON \"business_settings\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_business_settings_updated_by\" ON \"business_settings\" (\"updated_by\");\n\n-- Images and files stored in Stratus.\nCREATE TABLE IF NOT EXISTS \"media_files\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER,  -- → businesses.id in the platform database (checked by the API) · NULL = platform file\n  \"purpose\"                  INTEGER  NOT NULL CHECK (\"purpose\" >= 1),  -- MediaPurpose: 1 product, 2 category, 3 logo, 4 ticket, 5 poster\n  \"bucket\"                   TEXT     NOT NULL,  -- max 60\n  \"object_key\"               TEXT     NOT NULL UNIQUE,  -- max 255 · '<business_id>/products/<uuid>.webp'\n  \"thumb_key\"                TEXT,  -- max 255\n  \"content_type\"             TEXT     NOT NULL,  -- max 40 · image/webp | application/zip | …\n  \"bytes\"                    INTEGER  NOT NULL,  -- photos ≤ 51,200\n  \"width\"                    INTEGER,\n  \"height\"                   INTEGER,\n  \"original_bytes\"           INTEGER,\n  \"created_by\"               INTEGER  REFERENCES \"users\"(\"id\") ON DELETE SET NULL,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"media_files_updated_at\" AFTER UPDATE ON \"media_files\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"media_files\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_media_files_business_id\" ON \"media_files\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_media_files_created_by\" ON \"media_files\" (\"created_by\");\n\n-- Branches a staff member may work in (all-access roles don't need rows).\nCREATE TABLE IF NOT EXISTS \"user_branches\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"user_id\"                  INTEGER  NOT NULL REFERENCES \"users\"(\"id\") ON DELETE CASCADE,\n  \"branch_id\"                INTEGER  NOT NULL REFERENCES \"branches\"(\"id\") ON DELETE CASCADE,\n  \"uniq_key\"                 TEXT     NOT NULL UNIQUE,  -- max 60 · '<user_id>:<branch_id>'\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"user_branches_updated_at\" AFTER UPDATE ON \"user_branches\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"user_branches\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_user_branches_user_id\" ON \"user_branches\" (\"user_id\");\nCREATE INDEX IF NOT EXISTS \"ix_user_branches_branch_id\" ON \"user_branches\" (\"branch_id\");\n\n-- Purchase / stock-in bills.\nCREATE TABLE IF NOT EXISTS \"purchases\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"branch_id\"                INTEGER  NOT NULL REFERENCES \"branches\"(\"id\") ON DELETE CASCADE,\n  \"supplier_id\"              INTEGER  REFERENCES \"suppliers\"(\"id\") ON DELETE SET NULL,\n  \"number\"                   TEXT     NOT NULL,  -- max 30\n  \"supplier_bill_no\"         TEXT,  -- max 40\n  \"purchase_date\"            TEXT     NOT NULL CHECK (\"purchase_date\" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),\n  \"subtotal_minor\"           INTEGER  NOT NULL DEFAULT 0,\n  \"tax_minor\"                INTEGER  NOT NULL DEFAULT 0,\n  \"total_minor\"              INTEGER  NOT NULL DEFAULT 0,\n  \"paid_minor\"               INTEGER  NOT NULL DEFAULT 0,\n  \"status\"                   INTEGER  NOT NULL DEFAULT 2 CHECK (\"status\" >= 1),  -- PurchaseStatus: 1 draft, 2 final, 3 void\n  \"note\"                     TEXT,  -- max 255\n  \"created_by\"               INTEGER  REFERENCES \"users\"(\"id\") ON DELETE SET NULL,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"purchases_updated_at\" AFTER UPDATE ON \"purchases\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"purchases\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_purchases_business_id\" ON \"purchases\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_purchases_branch_id\" ON \"purchases\" (\"branch_id\");\nCREATE INDEX IF NOT EXISTS \"ix_purchases_supplier_id\" ON \"purchases\" (\"supplier_id\");\nCREATE INDEX IF NOT EXISTS \"ix_purchases_created_by\" ON \"purchases\" (\"created_by\");\n\n-- An order becomes a bill when it is completed (invoice_number is given then).\nCREATE TABLE IF NOT EXISTS \"orders\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"branch_id\"                INTEGER  NOT NULL REFERENCES \"branches\"(\"id\") ON DELETE CASCADE,\n  \"device_id\"                INTEGER  REFERENCES \"devices\"(\"id\") ON DELETE SET NULL,\n  \"client_uuid\"              TEXT     NOT NULL UNIQUE,  -- max 40 · idempotency / offline\n  \"order_number\"             TEXT     NOT NULL,  -- max 30 · #2209\n  \"invoice_number\"           TEXT,  -- max 30 · INV-11186, set on completion\n  \"invoice_key\"              TEXT     UNIQUE,  -- max 80 · '<business_id>:<invoice_number>'\n  \"order_type\"               INTEGER  NOT NULL CHECK (\"order_type\" >= 1),  -- OrderType: 1 dine_in, 2 takeaway, 3 delivery, 4 counter\n  \"source\"                   INTEGER  NOT NULL DEFAULT 1 CHECK (\"source\" >= 1),  -- OrderSource: 1 pos, 2 mobile, 3 table, 4 qr\n  \"status\"                   INTEGER  NOT NULL CHECK (\"status\" >= 1),  -- OrderStatus: 1 open, 2 completed, 3 cancelled\n  \"table_id\"                 INTEGER  REFERENCES \"dining_tables\"(\"id\") ON DELETE SET NULL,\n  \"customer_id\"              INTEGER  REFERENCES \"customers\"(\"id\") ON DELETE SET NULL,\n  \"customer_name\"            TEXT,  -- max 120 · snapshot / walk-in guest\n  \"customer_phone\"           TEXT,  -- max 16\n  \"customer_address\"         TEXT,  -- max 255 · delivery / QR takeaway\n  \"qr_status\"                INTEGER  CHECK (\"qr_status\" IS NULL OR \"qr_status\" >= 1),  -- QrStatus: 1 pending, 2 accepted, 3 rejected; NULL = not a QR order\n  \"fulfilment\"               INTEGER  CHECK (\"fulfilment\" IS NULL OR \"fulfilment\" >= 1),  -- Fulfilment: 1 new, 2 packing, 3 ready, 4 delivered; NULL = normal counter bill\n  \"price_list_id\"            INTEGER  REFERENCES \"price_lists\"(\"id\") ON DELETE SET NULL,\n  \"guests\"                   INTEGER,\n  \"subtotal_minor\"           INTEGER  NOT NULL DEFAULT 0,\n  \"discount_minor\"           INTEGER  NOT NULL DEFAULT 0,\n  \"discount_note\"            TEXT,  -- max 100\n  \"tax_minor\"                INTEGER  NOT NULL DEFAULT 0,\n  \"service_charge_minor\"     INTEGER  NOT NULL DEFAULT 0,\n  \"round_off_minor\"          INTEGER  NOT NULL DEFAULT 0,  -- ±\n  \"total_minor\"              INTEGER  NOT NULL DEFAULT 0,\n  \"paid_minor\"               INTEGER  NOT NULL DEFAULT 0,\n  \"balance_minor\"            INTEGER  NOT NULL DEFAULT 0,  -- due (credit)\n  \"returned_minor\"           INTEGER  NOT NULL DEFAULT 0,  -- sum of sale_returns\n  \"tax_breakup_json\"         TEXT,  -- [{rate_bp, taxable_minor, cgst_minor, sgst_minor, igst_minor}]\n  \"note\"                     TEXT,  -- max 255\n  \"billed_at\"                TEXT,\n  \"cancelled_at\"             TEXT,\n  \"cancel_reason\"            TEXT,  -- max 255\n  \"created_by\"               INTEGER  REFERENCES \"users\"(\"id\") ON DELETE SET NULL,  -- staff on the bill (commission)\n  \"updated_by\"               INTEGER  REFERENCES \"users\"(\"id\") ON DELETE SET NULL,\n  \"row_version\"              INTEGER  NOT NULL DEFAULT 1,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"orders_updated_at\" AFTER UPDATE ON \"orders\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"orders\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_orders_business_id_branch_id_status_created_at\" ON \"orders\" (\"business_id\", \"branch_id\", \"status\", \"created_at\");\nCREATE INDEX IF NOT EXISTS \"ix_orders_business_id_billed_at\" ON \"orders\" (\"business_id\", \"billed_at\");\nCREATE INDEX IF NOT EXISTS \"ix_orders_business_id_customer_id_status\" ON \"orders\" (\"business_id\", \"customer_id\", \"status\");\nCREATE INDEX IF NOT EXISTS \"ix_orders_business_id_table_id_status\" ON \"orders\" (\"business_id\", \"table_id\", \"status\");\nCREATE INDEX IF NOT EXISTS \"ix_orders_branch_id\" ON \"orders\" (\"branch_id\");\nCREATE INDEX IF NOT EXISTS \"ix_orders_device_id\" ON \"orders\" (\"device_id\");\nCREATE INDEX IF NOT EXISTS \"ix_orders_table_id\" ON \"orders\" (\"table_id\");\nCREATE INDEX IF NOT EXISTS \"ix_orders_customer_id\" ON \"orders\" (\"customer_id\");\nCREATE INDEX IF NOT EXISTS \"ix_orders_price_list_id\" ON \"orders\" (\"price_list_id\");\nCREATE INDEX IF NOT EXISTS \"ix_orders_created_by\" ON \"orders\" (\"created_by\");\nCREATE INDEX IF NOT EXISTS \"ix_orders_updated_by\" ON \"orders\" (\"updated_by\");\n\nCREATE TABLE IF NOT EXISTS \"expenses\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"branch_id\"                INTEGER  NOT NULL REFERENCES \"branches\"(\"id\") ON DELETE CASCADE,\n  \"category_id\"              INTEGER  REFERENCES \"expense_categories\"(\"id\") ON DELETE SET NULL,\n  \"expense_date\"             TEXT     NOT NULL,\n  \"amount_minor\"             INTEGER  NOT NULL,\n  \"method\"                   INTEGER  NOT NULL CHECK (\"method\" >= 1),  -- PayMethod: 1 cash, 2 upi, 3 card, 4 bank, 5 credit_note\n  \"notes\"                    TEXT,  -- max 255\n  \"ref_type\"                 INTEGER  CHECK (\"ref_type\" IS NULL OR \"ref_type\" >= 1),  -- ExpenseRef: 1 salary, 2 advance, 3 purchase\n  \"ref_id\"                   INTEGER,\n  \"is_voided\"                INTEGER  NOT NULL DEFAULT 0 CHECK (\"is_voided\" IN (0, 1)),\n  \"created_by\"               INTEGER  REFERENCES \"users\"(\"id\") ON DELETE SET NULL,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"expenses_updated_at\" AFTER UPDATE ON \"expenses\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"expenses\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_expenses_business_id_branch_id_expense_date\" ON \"expenses\" (\"business_id\", \"branch_id\", \"expense_date\");\nCREATE INDEX IF NOT EXISTS \"ix_expenses_branch_id\" ON \"expenses\" (\"branch_id\");\nCREATE INDEX IF NOT EXISTS \"ix_expenses_category_id\" ON \"expenses\" (\"category_id\");\nCREATE INDEX IF NOT EXISTS \"ix_expenses_created_by\" ON \"expenses\" (\"created_by\");\n\nCREATE TABLE IF NOT EXISTS \"attendance\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"branch_id\"                INTEGER  NOT NULL REFERENCES \"branches\"(\"id\") ON DELETE CASCADE,\n  \"user_id\"                  INTEGER  NOT NULL REFERENCES \"users\"(\"id\") ON DELETE CASCADE,\n  \"work_date\"                TEXT     NOT NULL CHECK (\"work_date\" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),\n  \"status\"                   INTEGER  NOT NULL CHECK (\"status\" >= 1),  -- AttendanceStatus: 1 present, 2 half, 3 absent, 4 leave\n  \"in_time\"                  TEXT,  -- max 5 · '09:30'\n  \"out_time\"                 TEXT,  -- max 5\n  \"note\"                     TEXT,  -- max 150\n  \"marked_by\"                INTEGER  REFERENCES \"users\"(\"id\") ON DELETE SET NULL,\n  \"uniq_key\"                 TEXT     NOT NULL UNIQUE,  -- max 60 · '<user_id>:<work_date>'\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"attendance_updated_at\" AFTER UPDATE ON \"attendance\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"attendance\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_attendance_business_id_work_date\" ON \"attendance\" (\"business_id\", \"work_date\");\nCREATE INDEX IF NOT EXISTS \"ix_attendance_branch_id\" ON \"attendance\" (\"branch_id\");\nCREATE INDEX IF NOT EXISTS \"ix_attendance_user_id\" ON \"attendance\" (\"user_id\");\nCREATE INDEX IF NOT EXISTS \"ix_attendance_marked_by\" ON \"attendance\" (\"marked_by\");\n\n-- What the shop's staff did (Settings → Audit log).\nCREATE TABLE IF NOT EXISTS \"audit_logs\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"branch_id\"                INTEGER  REFERENCES \"branches\"(\"id\") ON DELETE SET NULL,\n  \"user_id\"                  INTEGER  REFERENCES \"users\"(\"id\") ON DELETE SET NULL,\n  \"support_admin_id\"         INTEGER,  -- → platform_admins.id in the platform database (checked by the API) · set during a support view\n  \"entity\"                   INTEGER  NOT NULL CHECK (\"entity\" >= 1),  -- AuditEntity: 1 order, 2 payment, 3 product, 4 category, 5 customer, 6 inventory, 7 expense, 8 user, 9 role, 10 branch, 11 settings, 12 whatsapp, 13 return, 14 staff, 15 table\n  \"entity_id\"                INTEGER,\n  \"action\"                   INTEGER  NOT NULL CHECK (\"action\" >= 1),  -- AuditAction: 1 create, 2 update, 3 delete, 4 cancel, 5 void, 6 login, 7 printer, 8 enable, 9 disconnect, 10 import, 11 export\n  \"detail\"                   TEXT,  -- max 255\n  \"changes_json\"             TEXT,  -- {field: [old, new]}\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"audit_logs_updated_at\" AFTER UPDATE ON \"audit_logs\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"audit_logs\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_audit_logs_business_id_created_at\" ON \"audit_logs\" (\"business_id\", \"created_at\");\nCREATE INDEX IF NOT EXISTS \"ix_audit_logs_branch_id\" ON \"audit_logs\" (\"branch_id\");\nCREATE INDEX IF NOT EXISTS \"ix_audit_logs_user_id\" ON \"audit_logs\" (\"user_id\");\nCREATE INDEX IF NOT EXISTS \"ix_audit_logs_support_admin_id\" ON \"audit_logs\" (\"support_admin_id\");\n\nCREATE TABLE IF NOT EXISTS \"categories\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"parent_id\"                INTEGER  REFERENCES \"categories\"(\"id\") ON DELETE SET NULL,  -- sub-categories later\n  \"name\"                     TEXT     NOT NULL,  -- max 80\n  \"emoji\"                    TEXT,  -- max 8\n  \"image_media_id\"           INTEGER  REFERENCES \"media_files\"(\"id\") ON DELETE SET NULL,\n  \"sort_order\"               INTEGER  NOT NULL DEFAULT 0,\n  \"is_active\"                INTEGER  NOT NULL DEFAULT 1 CHECK (\"is_active\" IN (0, 1)),\n  \"uniq_key\"                 TEXT     NOT NULL UNIQUE,  -- max 120 · '<business_id>:<lower(name)>'\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"categories_updated_at\" AFTER UPDATE ON \"categories\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"categories\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_categories_business_id\" ON \"categories\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_categories_parent_id\" ON \"categories\" (\"parent_id\");\nCREATE INDEX IF NOT EXISTS \"ix_categories_image_media_id\" ON \"categories\" (\"image_media_id\");\n\n-- Returns / credit notes.\nCREATE TABLE IF NOT EXISTS \"sale_returns\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"branch_id\"                INTEGER  NOT NULL REFERENCES \"branches\"(\"id\") ON DELETE CASCADE,\n  \"order_id\"                 INTEGER  REFERENCES \"orders\"(\"id\") ON DELETE SET NULL,\n  \"customer_id\"              INTEGER  REFERENCES \"customers\"(\"id\") ON DELETE SET NULL,\n  \"client_uuid\"              TEXT     NOT NULL UNIQUE,  -- max 40\n  \"number\"                   TEXT     NOT NULL,  -- max 30 · CN-1001\n  \"number_key\"               TEXT     NOT NULL UNIQUE,  -- max 80 · '<business_id>:<number>'\n  \"invoice_number\"           TEXT     NOT NULL,  -- max 30 · snapshot of the bill\n  \"reason\"                   INTEGER  NOT NULL CHECK (\"reason\" >= 1),  -- ReturnReason: 1 damaged, 2 wrong_item, 3 not_needed, 4 expired, 5 quality, 6 other\n  \"settle\"                   INTEGER  NOT NULL CHECK (\"settle\" >= 1),  -- ReturnSettle: 1 refund, 2 exchange, 3 credit_note\n  \"note\"                     TEXT,  -- max 255\n  \"total_minor\"              INTEGER  NOT NULL,\n  \"tax_minor\"                INTEGER  NOT NULL DEFAULT 0,  -- tax share of the total\n  \"due_adjusted_minor\"       INTEGER  NOT NULL DEFAULT 0,  -- taken off the bill's balance first\n  \"refunded_minor\"           INTEGER  NOT NULL DEFAULT 0,\n  \"refund_method\"            INTEGER  CHECK (\"refund_method\" IS NULL OR \"refund_method\" >= 1),  -- PayMethod: 1 cash, 2 upi, 3 card, 4 bank, 5 credit_note\n  \"credit_issued_minor\"      INTEGER  NOT NULL DEFAULT 0,\n  \"credit_remaining_minor\"   INTEGER  NOT NULL DEFAULT 0,  -- reduced by payments with method credit_note\n  \"credit_expires_on\"        TEXT     CHECK (\"credit_expires_on\" IS NULL OR \"credit_expires_on\" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),\n  \"created_by\"               INTEGER  REFERENCES \"users\"(\"id\") ON DELETE SET NULL,\n  \"row_version\"              INTEGER  NOT NULL DEFAULT 1,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"sale_returns_updated_at\" AFTER UPDATE ON \"sale_returns\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"sale_returns\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_sale_returns_business_id_branch_id_created_at\" ON \"sale_returns\" (\"business_id\", \"branch_id\", \"created_at\");\nCREATE INDEX IF NOT EXISTS \"ix_sale_returns_order_id\" ON \"sale_returns\" (\"order_id\");\nCREATE INDEX IF NOT EXISTS \"ix_sale_returns_branch_id\" ON \"sale_returns\" (\"branch_id\");\nCREATE INDEX IF NOT EXISTS \"ix_sale_returns_customer_id\" ON \"sale_returns\" (\"customer_id\");\nCREATE INDEX IF NOT EXISTS \"ix_sale_returns_created_by\" ON \"sale_returns\" (\"created_by\");\n\nCREATE TABLE IF NOT EXISTS \"kitchen_tickets\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"branch_id\"                INTEGER  NOT NULL REFERENCES \"branches\"(\"id\") ON DELETE CASCADE,\n  \"order_id\"                 INTEGER  NOT NULL REFERENCES \"orders\"(\"id\") ON DELETE CASCADE,\n  \"client_uuid\"              TEXT     NOT NULL UNIQUE,  -- max 40\n  \"number\"                   TEXT     NOT NULL,  -- max 20 · KOT-0014\n  \"order_number\"             TEXT     NOT NULL,  -- max 30 · snapshot for the kitchen screen\n  \"order_type\"               INTEGER  NOT NULL,  -- OrderType (snapshot)\n  \"station\"                  TEXT,  -- max 30 · kitchen | bar | grill (later)\n  \"status\"                   INTEGER  NOT NULL DEFAULT 1 CHECK (\"status\" >= 1),  -- KotStatus: 1 new, 2 preparing, 3 ready, 4 completed, 5 cancelled\n  \"table_label\"              TEXT,  -- max 20 · snapshot\n  \"started_at\"               TEXT,\n  \"ready_at\"                 TEXT,\n  \"completed_at\"             TEXT,  -- served / handed over\n  \"created_by\"               INTEGER  REFERENCES \"users\"(\"id\") ON DELETE SET NULL,\n  \"row_version\"              INTEGER  NOT NULL DEFAULT 1,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"kitchen_tickets_updated_at\" AFTER UPDATE ON \"kitchen_tickets\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"kitchen_tickets\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_kitchen_tickets_business_id_branch_id_status\" ON \"kitchen_tickets\" (\"business_id\", \"branch_id\", \"status\");\nCREATE INDEX IF NOT EXISTS \"ix_kitchen_tickets_order_id\" ON \"kitchen_tickets\" (\"order_id\");\nCREATE INDEX IF NOT EXISTS \"ix_kitchen_tickets_branch_id\" ON \"kitchen_tickets\" (\"branch_id\");\nCREATE INDEX IF NOT EXISTS \"ix_kitchen_tickets_created_by\" ON \"kitchen_tickets\" (\"created_by\");\n\nCREATE TABLE IF NOT EXISTS \"salary_payments\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"user_id\"                  INTEGER  REFERENCES \"users\"(\"id\") ON DELETE SET NULL,\n  \"month\"                    TEXT     NOT NULL,  -- max 7 · '2026-10' snapshot of how it was worked out, so an old salary slip reprints exactly\n  \"pay_type\"                 INTEGER  NOT NULL,  -- PayType\n  \"rate_minor\"               INTEGER  NOT NULL,  -- monthly salary or daily rate at that time\n  \"days_in_month\"            INTEGER  NOT NULL,\n  \"present_days\"             INTEGER  NOT NULL DEFAULT 0,\n  \"half_days\"                INTEGER  NOT NULL DEFAULT 0,\n  \"leave_days\"               INTEGER  NOT NULL DEFAULT 0,\n  \"absent_days\"              INTEGER  NOT NULL DEFAULT 0,\n  \"unmarked_days\"            INTEGER  NOT NULL DEFAULT 0,\n  \"commission_sales_minor\"   INTEGER  NOT NULL DEFAULT 0,  -- net sales the commission was worked out on\n  \"base_minor\"               INTEGER  NOT NULL,\n  \"commission_minor\"         INTEGER  NOT NULL DEFAULT 0,\n  \"bonus_minor\"              INTEGER  NOT NULL DEFAULT 0,\n  \"deduction_minor\"          INTEGER  NOT NULL DEFAULT 0,\n  \"advances_minor\"           INTEGER  NOT NULL DEFAULT 0,\n  \"net_minor\"                INTEGER  NOT NULL,\n  \"method\"                   INTEGER  NOT NULL,  -- PayMethod\n  \"note\"                     TEXT,  -- max 150\n  \"expense_id\"               INTEGER  REFERENCES \"expenses\"(\"id\") ON DELETE SET NULL,\n  \"paid_by\"                  INTEGER  REFERENCES \"users\"(\"id\") ON DELETE SET NULL,\n  \"uniq_key\"                 TEXT     NOT NULL UNIQUE,  -- max 40 · '<user_id>:<month>' — no double pay\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"salary_payments_updated_at\" AFTER UPDATE ON \"salary_payments\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"salary_payments\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_salary_payments_business_id\" ON \"salary_payments\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_salary_payments_user_id\" ON \"salary_payments\" (\"user_id\");\nCREATE INDEX IF NOT EXISTS \"ix_salary_payments_expense_id\" ON \"salary_payments\" (\"expense_id\");\nCREATE INDEX IF NOT EXISTS \"ix_salary_payments_paid_by\" ON \"salary_payments\" (\"paid_by\");\n\nCREATE TABLE IF NOT EXISTS \"campaigns\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"channel\"                  INTEGER  NOT NULL DEFAULT 1 CHECK (\"channel\" >= 1),  -- Channel: 1 whatsapp\n  \"campaign_date\"            TEXT     NOT NULL CHECK (\"campaign_date\" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),\n  \"message\"                  TEXT     NOT NULL,  -- offer details (up to 300 characters)\n  \"product_ids_json\"         TEXT,\n  \"poster_media_id\"          INTEGER  REFERENCES \"media_files\"(\"id\") ON DELETE SET NULL,\n  \"sent_count\"               INTEGER  NOT NULL DEFAULT 0,\n  \"created_by\"               INTEGER  REFERENCES \"users\"(\"id\") ON DELETE SET NULL,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"campaigns_updated_at\" AFTER UPDATE ON \"campaigns\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"campaigns\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_campaigns_business_id\" ON \"campaigns\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_campaigns_poster_media_id\" ON \"campaigns\" (\"poster_media_id\");\nCREATE INDEX IF NOT EXISTS \"ix_campaigns_created_by\" ON \"campaigns\" (\"created_by\");\n\nCREATE TABLE IF NOT EXISTS \"products\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"category_id\"              INTEGER  REFERENCES \"categories\"(\"id\") ON DELETE SET NULL,\n  \"tax_rate_id\"              INTEGER  REFERENCES \"tax_rates\"(\"id\") ON DELETE SET NULL,\n  \"name\"                     TEXT     NOT NULL,  -- max 150\n  \"name_local\"               TEXT,  -- max 150 · Tamil name for bills / labels\n  \"kind\"                     INTEGER  NOT NULL DEFAULT 1 CHECK (\"kind\" >= 1),  -- ProductKind: 1 goods, 2 service\n  \"sku\"                      TEXT,  -- max 40\n  \"barcode\"                  TEXT,  -- max 40\n  \"barcode_key\"              TEXT     UNIQUE,  -- max 80 · '<business_id>:<barcode>' (NULL when no barcode)\n  \"hsn_code\"                 TEXT,  -- max 10\n  \"unit\"                     TEXT     NOT NULL DEFAULT 'pc',  -- max 10 · pc | kg | g | ltr | ml | pack | box | bottle | plate | … (open list: templates and CSV add more)\n  \"price_minor\"              INTEGER  NOT NULL DEFAULT 0,  -- retail price (default price list)\n  \"mrp_minor\"                INTEGER,\n  \"cost_minor\"               INTEGER,\n  \"is_veg\"                   INTEGER  CHECK (\"is_veg\" IS NULL OR \"is_veg\" IN (0, 1)),  -- food only\n  \"sends_to_kitchen\"         INTEGER  NOT NULL DEFAULT 1 CHECK (\"sends_to_kitchen\" IN (0, 1)),  -- KOT\n  \"track_stock\"              INTEGER  NOT NULL DEFAULT 0 CHECK (\"track_stock\" IN (0, 1)),\n  \"track_batches\"            INTEGER  NOT NULL DEFAULT 0 CHECK (\"track_batches\" IN (0, 1)),  -- batch & expiry\n  \"low_stock_milli\"          INTEGER  NOT NULL DEFAULT 0,\n  \"image_media_id\"           INTEGER  REFERENCES \"media_files\"(\"id\") ON DELETE SET NULL,\n  \"emoji\"                    TEXT,  -- max 8\n  \"sort_order\"               INTEGER  NOT NULL DEFAULT 0,\n  \"is_active\"                INTEGER  NOT NULL DEFAULT 1 CHECK (\"is_active\" IN (0, 1)),\n  \"row_version\"              INTEGER  NOT NULL DEFAULT 1,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"products_updated_at\" AFTER UPDATE ON \"products\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"products\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_products_business_id_is_active\" ON \"products\" (\"business_id\", \"is_active\");\nCREATE INDEX IF NOT EXISTS \"ix_products_category_id\" ON \"products\" (\"category_id\");\nCREATE INDEX IF NOT EXISTS \"ix_products_tax_rate_id\" ON \"products\" (\"tax_rate_id\");\nCREATE INDEX IF NOT EXISTS \"ix_products_image_media_id\" ON \"products\" (\"image_media_id\");\n\n-- Every money movement: sale, due collection, refund. Never edited — voided and re-entered.\nCREATE TABLE IF NOT EXISTS \"payments\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"branch_id\"                INTEGER  NOT NULL REFERENCES \"branches\"(\"id\") ON DELETE CASCADE,\n  \"order_id\"                 INTEGER  REFERENCES \"orders\"(\"id\") ON DELETE SET NULL,  -- NULL for a due collection across bills\n  \"customer_id\"              INTEGER  REFERENCES \"customers\"(\"id\") ON DELETE SET NULL,\n  \"return_id\"                INTEGER  REFERENCES \"sale_returns\"(\"id\") ON DELETE SET NULL,  -- refund of / payment with this credit note\n  \"client_uuid\"              TEXT     NOT NULL UNIQUE,  -- max 40\n  \"kind\"                     INTEGER  NOT NULL CHECK (\"kind\" >= 1),  -- PaymentKind: 1 sale, 2 due_collection, 3 refund\n  \"method\"                   INTEGER  NOT NULL CHECK (\"method\" >= 1),  -- PayMethod: 1 cash, 2 upi, 3 card, 4 bank, 5 credit_note\n  \"amount_minor\"             INTEGER  NOT NULL,\n  \"reference\"                TEXT,  -- max 80 · UPI ref / card last 4\n  \"is_voided\"                INTEGER  NOT NULL DEFAULT 0 CHECK (\"is_voided\" IN (0, 1)),\n  \"voided_at\"                TEXT,\n  \"void_reason\"              TEXT,  -- max 255\n  \"created_by\"               INTEGER  REFERENCES \"users\"(\"id\") ON DELETE SET NULL,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"payments_updated_at\" AFTER UPDATE ON \"payments\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"payments\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_payments_business_id_branch_id_created_at\" ON \"payments\" (\"business_id\", \"branch_id\", \"created_at\");\nCREATE INDEX IF NOT EXISTS \"ix_payments_order_id\" ON \"payments\" (\"order_id\");\nCREATE INDEX IF NOT EXISTS \"ix_payments_business_id_customer_id\" ON \"payments\" (\"business_id\", \"customer_id\");\nCREATE INDEX IF NOT EXISTS \"ix_payments_branch_id\" ON \"payments\" (\"branch_id\");\nCREATE INDEX IF NOT EXISTS \"ix_payments_customer_id\" ON \"payments\" (\"customer_id\");\nCREATE INDEX IF NOT EXISTS \"ix_payments_return_id\" ON \"payments\" (\"return_id\");\nCREATE INDEX IF NOT EXISTS \"ix_payments_created_by\" ON \"payments\" (\"created_by\");\n\nCREATE TABLE IF NOT EXISTS \"staff_advances\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"user_id\"                  INTEGER  REFERENCES \"users\"(\"id\") ON DELETE SET NULL,\n  \"amount_minor\"             INTEGER  NOT NULL,\n  \"method\"                   INTEGER  NOT NULL,  -- PayMethod\n  \"given_on\"                 TEXT     NOT NULL CHECK (\"given_on\" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),\n  \"note\"                     TEXT,  -- max 150\n  \"expense_id\"               INTEGER  REFERENCES \"expenses\"(\"id\") ON DELETE SET NULL,\n  \"salary_payment_id\"        INTEGER  REFERENCES \"salary_payments\"(\"id\") ON DELETE SET NULL,  -- set when deducted\n  \"given_by\"                 INTEGER  REFERENCES \"users\"(\"id\") ON DELETE SET NULL,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"staff_advances_updated_at\" AFTER UPDATE ON \"staff_advances\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"staff_advances\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_staff_advances_business_id\" ON \"staff_advances\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_staff_advances_user_id\" ON \"staff_advances\" (\"user_id\");\nCREATE INDEX IF NOT EXISTS \"ix_staff_advances_expense_id\" ON \"staff_advances\" (\"expense_id\");\nCREATE INDEX IF NOT EXISTS \"ix_staff_advances_salary_payment_id\" ON \"staff_advances\" (\"salary_payment_id\");\nCREATE INDEX IF NOT EXISTS \"ix_staff_advances_given_by\" ON \"staff_advances\" (\"given_by\");\n\n-- Every WhatsApp message: bills, offers, tests, and platform renewal reminders (business_id = customer).\nCREATE TABLE IF NOT EXISTS \"whatsapp_messages\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER,  -- → businesses.id in the platform database (checked by the API)\n  \"sender\"                   INTEGER  NOT NULL CHECK (\"sender\" >= 1),  -- WaSender: 1 business, 2 platform\n  \"kind\"                     INTEGER  NOT NULL CHECK (\"kind\" >= 1),  -- WaMessageKind: 1 bill, 2 offer, 3 test, 4 renewal_reminder\n  \"to_number\"                TEXT     NOT NULL,  -- max 16\n  \"customer_id\"              INTEGER  REFERENCES \"customers\"(\"id\") ON DELETE SET NULL,\n  \"order_id\"                 INTEGER  REFERENCES \"orders\"(\"id\") ON DELETE SET NULL,\n  \"campaign_id\"              INTEGER  REFERENCES \"campaigns\"(\"id\") ON DELETE SET NULL,\n  \"template_id\"              INTEGER  REFERENCES \"whatsapp_templates\"(\"id\") ON DELETE SET NULL,\n  \"body\"                     TEXT     NOT NULL,\n  \"attachment_media_id\"      INTEGER  REFERENCES \"media_files\"(\"id\") ON DELETE SET NULL,\n  \"meta_message_id\"          TEXT     UNIQUE,  -- max 80 · updated by Meta's webhook\n  \"status\"                   INTEGER  NOT NULL DEFAULT 1 CHECK (\"status\" >= 1),  -- WaMessageStatus: 1 queued, 2 sent, 3 delivered, 4 read, 5 failed\n  \"error\"                    TEXT,  -- max 255\n  \"status_at\"                TEXT,\n  \"created_by\"               INTEGER  REFERENCES \"users\"(\"id\") ON DELETE SET NULL,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"whatsapp_messages_updated_at\" AFTER UPDATE ON \"whatsapp_messages\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"whatsapp_messages\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_whatsapp_messages_business_id_created_at\" ON \"whatsapp_messages\" (\"business_id\", \"created_at\");\nCREATE INDEX IF NOT EXISTS \"ix_whatsapp_messages_campaign_id\" ON \"whatsapp_messages\" (\"campaign_id\");\nCREATE INDEX IF NOT EXISTS \"ix_whatsapp_messages_customer_id\" ON \"whatsapp_messages\" (\"customer_id\");\nCREATE INDEX IF NOT EXISTS \"ix_whatsapp_messages_order_id\" ON \"whatsapp_messages\" (\"order_id\");\nCREATE INDEX IF NOT EXISTS \"ix_whatsapp_messages_template_id\" ON \"whatsapp_messages\" (\"template_id\");\nCREATE INDEX IF NOT EXISTS \"ix_whatsapp_messages_attachment_media_id\" ON \"whatsapp_messages\" (\"attachment_media_id\");\nCREATE INDEX IF NOT EXISTS \"ix_whatsapp_messages_created_by\" ON \"whatsapp_messages\" (\"created_by\");\n\nCREATE TABLE IF NOT EXISTS \"product_variants\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"product_id\"               INTEGER  NOT NULL REFERENCES \"products\"(\"id\") ON DELETE CASCADE,\n  \"name\"                     TEXT     NOT NULL,  -- max 60 · Half | Full | 500 ml\n  \"price_minor\"              INTEGER  NOT NULL,\n  \"barcode\"                  TEXT,  -- max 40\n  \"barcode_key\"              TEXT     UNIQUE,  -- max 80\n  \"sort_order\"               INTEGER  NOT NULL DEFAULT 0,\n  \"is_active\"                INTEGER  NOT NULL DEFAULT 1 CHECK (\"is_active\" IN (0, 1)),\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"product_variants_updated_at\" AFTER UPDATE ON \"product_variants\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"product_variants\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_product_variants_business_id\" ON \"product_variants\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_product_variants_product_id\" ON \"product_variants\" (\"product_id\");\n\nCREATE TABLE IF NOT EXISTS \"product_addons\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"product_id\"               INTEGER  NOT NULL REFERENCES \"products\"(\"id\") ON DELETE CASCADE,\n  \"name\"                     TEXT     NOT NULL,  -- max 60 · Extra cheese\n  \"price_minor\"              INTEGER  NOT NULL DEFAULT 0,\n  \"sort_order\"               INTEGER  NOT NULL DEFAULT 0,\n  \"is_active\"                INTEGER  NOT NULL DEFAULT 1 CHECK (\"is_active\" IN (0, 1)),\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"product_addons_updated_at\" AFTER UPDATE ON \"product_addons\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"product_addons\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_product_addons_business_id\" ON \"product_addons\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_product_addons_product_id\" ON \"product_addons\" (\"product_id\");\n\n-- Daily specials (offer price / tag for a date).\nCREATE TABLE IF NOT EXISTS \"daily_specials\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"branch_id\"                INTEGER  REFERENCES \"branches\"(\"id\") ON DELETE CASCADE,  -- NULL = all branches\n  \"product_id\"               INTEGER  NOT NULL REFERENCES \"products\"(\"id\") ON DELETE CASCADE,\n  \"special_date\"             TEXT     NOT NULL CHECK (\"special_date\" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),\n  \"offer_price_minor\"        INTEGER,\n  \"tag\"                      TEXT,  -- max 40 · 'Chef’s special'\n  \"sort_order\"               INTEGER  NOT NULL DEFAULT 0,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"daily_specials_updated_at\" AFTER UPDATE ON \"daily_specials\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"daily_specials\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_daily_specials_business_id_special_date\" ON \"daily_specials\" (\"business_id\", \"special_date\");\nCREATE INDEX IF NOT EXISTS \"ix_daily_specials_branch_id\" ON \"daily_specials\" (\"branch_id\");\nCREATE INDEX IF NOT EXISTS \"ix_daily_specials_product_id\" ON \"daily_specials\" (\"product_id\");\n\n-- Current stock per item per branch (kept in step with stock_movements by the backend).\nCREATE TABLE IF NOT EXISTS \"branch_stock\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"branch_id\"                INTEGER  NOT NULL REFERENCES \"branches\"(\"id\") ON DELETE CASCADE,\n  \"product_id\"               INTEGER  NOT NULL REFERENCES \"products\"(\"id\") ON DELETE CASCADE,\n  \"qty_milli\"                INTEGER  NOT NULL DEFAULT 0,\n  \"uniq_key\"                 TEXT     NOT NULL UNIQUE,  -- max 60 · '<branch_id>:<product_id>'\n  \"row_version\"              INTEGER  NOT NULL DEFAULT 1,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"branch_stock_updated_at\" AFTER UPDATE ON \"branch_stock\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"branch_stock\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_branch_stock_business_id\" ON \"branch_stock\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_branch_stock_branch_id\" ON \"branch_stock\" (\"branch_id\");\nCREATE INDEX IF NOT EXISTS \"ix_branch_stock_product_id\" ON \"branch_stock\" (\"product_id\");\n\nCREATE TABLE IF NOT EXISTS \"purchase_items\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"purchase_id\"              INTEGER  NOT NULL REFERENCES \"purchases\"(\"id\") ON DELETE CASCADE,\n  \"product_id\"               INTEGER  REFERENCES \"products\"(\"id\") ON DELETE SET NULL,\n  \"product_name\"             TEXT     NOT NULL,  -- max 150 · snapshot\n  \"qty_milli\"                INTEGER  NOT NULL,\n  \"cost_minor\"               INTEGER  NOT NULL,  -- per unit\n  \"tax_bp\"                   INTEGER  NOT NULL DEFAULT 0,\n  \"batch_no\"                 TEXT,  -- max 40\n  \"expiry_date\"              TEXT     CHECK (\"expiry_date\" IS NULL OR \"expiry_date\" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"purchase_items_updated_at\" AFTER UPDATE ON \"purchase_items\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"purchase_items\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_purchase_items_business_id\" ON \"purchase_items\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_purchase_items_purchase_id\" ON \"purchase_items\" (\"purchase_id\");\nCREATE INDEX IF NOT EXISTS \"ix_purchase_items_product_id\" ON \"purchase_items\" (\"product_id\");\n\n-- Due collected once and spread across several bills.\nCREATE TABLE IF NOT EXISTS \"payment_allocations\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"payment_id\"               INTEGER  NOT NULL REFERENCES \"payments\"(\"id\") ON DELETE CASCADE,\n  \"order_id\"                 INTEGER  REFERENCES \"orders\"(\"id\") ON DELETE SET NULL,\n  \"amount_minor\"             INTEGER  NOT NULL,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"payment_allocations_updated_at\" AFTER UPDATE ON \"payment_allocations\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"payment_allocations\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_payment_allocations_business_id\" ON \"payment_allocations\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_payment_allocations_payment_id\" ON \"payment_allocations\" (\"payment_id\");\nCREATE INDEX IF NOT EXISTS \"ix_payment_allocations_order_id\" ON \"payment_allocations\" (\"order_id\");\n\n-- Price of an item (or one of its sizes) on a non-default price list. Missing row → retail price.\nCREATE TABLE IF NOT EXISTS \"product_prices\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"price_list_id\"            INTEGER  NOT NULL REFERENCES \"price_lists\"(\"id\") ON DELETE CASCADE,\n  \"product_id\"               INTEGER  NOT NULL REFERENCES \"products\"(\"id\") ON DELETE CASCADE,\n  \"variant_id\"               INTEGER  REFERENCES \"product_variants\"(\"id\") ON DELETE CASCADE,\n  \"price_minor\"              INTEGER  NOT NULL,\n  \"uniq_key\"                 TEXT     NOT NULL UNIQUE,  -- max 80 · '<price_list_id>:<product_id>:<variant_id|0>'\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"product_prices_updated_at\" AFTER UPDATE ON \"product_prices\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"product_prices\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_product_prices_business_id\" ON \"product_prices\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_product_prices_price_list_id\" ON \"product_prices\" (\"price_list_id\");\nCREATE INDEX IF NOT EXISTS \"ix_product_prices_product_id\" ON \"product_prices\" (\"product_id\");\nCREATE INDEX IF NOT EXISTS \"ix_product_prices_variant_id\" ON \"product_prices\" (\"variant_id\");\n\n-- Batches with expiry (milk, bread, medicines). Sold first-expiry-first-out.\nCREATE TABLE IF NOT EXISTS \"stock_batches\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"branch_id\"                INTEGER  NOT NULL REFERENCES \"branches\"(\"id\") ON DELETE CASCADE,\n  \"product_id\"               INTEGER  NOT NULL REFERENCES \"products\"(\"id\") ON DELETE CASCADE,\n  \"purchase_item_id\"         INTEGER  REFERENCES \"purchase_items\"(\"id\") ON DELETE SET NULL,\n  \"batch_no\"                 TEXT,  -- max 40\n  \"expiry_date\"              TEXT     CHECK (\"expiry_date\" IS NULL OR \"expiry_date\" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),\n  \"qty_in_milli\"             INTEGER  NOT NULL,\n  \"qty_left_milli\"           INTEGER  NOT NULL,\n  \"cost_minor\"               INTEGER,\n  \"row_version\"              INTEGER  NOT NULL DEFAULT 1,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"stock_batches_updated_at\" AFTER UPDATE ON \"stock_batches\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"stock_batches\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_stock_batches_product_id_branch_id_expiry_date\" ON \"stock_batches\" (\"product_id\", \"branch_id\", \"expiry_date\");\nCREATE INDEX IF NOT EXISTS \"ix_stock_batches_business_id\" ON \"stock_batches\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_stock_batches_branch_id\" ON \"stock_batches\" (\"branch_id\");\nCREATE INDEX IF NOT EXISTS \"ix_stock_batches_purchase_item_id\" ON \"stock_batches\" (\"purchase_item_id\");\n\nCREATE TABLE IF NOT EXISTS \"order_items\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"order_id\"                 INTEGER  NOT NULL REFERENCES \"orders\"(\"id\") ON DELETE CASCADE,\n  \"product_id\"               INTEGER  REFERENCES \"products\"(\"id\") ON DELETE SET NULL,\n  \"variant_id\"               INTEGER  REFERENCES \"product_variants\"(\"id\") ON DELETE SET NULL,\n  \"product_name\"             TEXT     NOT NULL,  -- max 150 · snapshot: 'French Fries'\n  \"variant_name\"             TEXT,  -- max 60 · snapshot: 'Regular'\n  \"unit\"                     TEXT     NOT NULL,  -- max 10\n  \"qty_milli\"                INTEGER  NOT NULL,\n  \"unit_price_minor\"         INTEGER  NOT NULL,  -- base / size price + add-ons\n  \"price_list_id\"            INTEGER  REFERENCES \"price_lists\"(\"id\") ON DELETE SET NULL,  -- which list priced it\n  \"discount_minor\"           INTEGER  NOT NULL DEFAULT 0,\n  \"tax_bp\"                   INTEGER  NOT NULL DEFAULT 0,\n  \"tax_minor\"                INTEGER  NOT NULL DEFAULT 0,\n  \"line_total_minor\"         INTEGER  NOT NULL,\n  \"cost_minor\"               INTEGER,  -- snapshot for profit reports\n  \"note\"                     TEXT,  -- max 150 · 'less spicy'\n  \"kot_qty_milli\"            INTEGER  NOT NULL DEFAULT 0,  -- qty already sent to the kitchen (next KOT sends qty − this)\n  \"sort_order\"               INTEGER  NOT NULL DEFAULT 0,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"order_items_updated_at\" AFTER UPDATE ON \"order_items\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"order_items\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_order_items_order_id_sort_order\" ON \"order_items\" (\"order_id\", \"sort_order\");\nCREATE INDEX IF NOT EXISTS \"ix_order_items_product_id\" ON \"order_items\" (\"product_id\");\nCREATE INDEX IF NOT EXISTS \"ix_order_items_business_id\" ON \"order_items\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_order_items_variant_id\" ON \"order_items\" (\"variant_id\");\nCREATE INDEX IF NOT EXISTS \"ix_order_items_price_list_id\" ON \"order_items\" (\"price_list_id\");\n\n-- Every stock change. The ledger that branch_stock / stock_batches are rebuilt from.\nCREATE TABLE IF NOT EXISTS \"stock_movements\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"branch_id\"                INTEGER  NOT NULL REFERENCES \"branches\"(\"id\") ON DELETE CASCADE,\n  \"product_id\"               INTEGER  NOT NULL REFERENCES \"products\"(\"id\") ON DELETE CASCADE,\n  \"batch_id\"                 INTEGER  REFERENCES \"stock_batches\"(\"id\") ON DELETE SET NULL,\n  \"reason\"                   INTEGER  NOT NULL CHECK (\"reason\" >= 1),  -- StockReason: 1 opening, 2 purchase, 3 sale, 4 return, 5 wastage, 6 damage, 7 expired, 8 adjustment, 9 transfer_in, 10 transfer_out\n  \"qty_milli\"                INTEGER  NOT NULL,  -- + in, − out\n  \"balance_milli\"            INTEGER  NOT NULL,  -- stock after this movement\n  \"ref_type\"                 INTEGER  CHECK (\"ref_type\" IS NULL OR \"ref_type\" >= 1),  -- StockRef: 1 order, 2 purchase, 3 return, 4 transfer\n  \"ref_id\"                   INTEGER,  -- ROWID in that table\n  \"note\"                     TEXT,  -- max 255\n  \"created_by\"               INTEGER  REFERENCES \"users\"(\"id\") ON DELETE SET NULL,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"stock_movements_updated_at\" AFTER UPDATE ON \"stock_movements\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"stock_movements\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_stock_movements_business_id_product_id_created_at\" ON \"stock_movements\" (\"business_id\", \"product_id\", \"created_at\");\nCREATE INDEX IF NOT EXISTS \"ix_stock_movements_business_id_branch_id_created_at\" ON \"stock_movements\" (\"business_id\", \"branch_id\", \"created_at\");\nCREATE INDEX IF NOT EXISTS \"ix_stock_movements_branch_id\" ON \"stock_movements\" (\"branch_id\");\nCREATE INDEX IF NOT EXISTS \"ix_stock_movements_product_id\" ON \"stock_movements\" (\"product_id\");\nCREATE INDEX IF NOT EXISTS \"ix_stock_movements_batch_id\" ON \"stock_movements\" (\"batch_id\");\nCREATE INDEX IF NOT EXISTS \"ix_stock_movements_created_by\" ON \"stock_movements\" (\"created_by\");\n\nCREATE TABLE IF NOT EXISTS \"order_item_addons\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"order_item_id\"            INTEGER  NOT NULL REFERENCES \"order_items\"(\"id\") ON DELETE CASCADE,\n  \"addon_id\"                 INTEGER  REFERENCES \"product_addons\"(\"id\") ON DELETE SET NULL,\n  \"name\"                     TEXT     NOT NULL,  -- max 60 · snapshot\n  \"price_minor\"              INTEGER  NOT NULL,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"order_item_addons_updated_at\" AFTER UPDATE ON \"order_item_addons\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"order_item_addons\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_order_item_addons_business_id\" ON \"order_item_addons\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_order_item_addons_order_item_id\" ON \"order_item_addons\" (\"order_item_id\");\nCREATE INDEX IF NOT EXISTS \"ix_order_item_addons_addon_id\" ON \"order_item_addons\" (\"addon_id\");\n\n-- Batch(es) a sold line came from (FEFO), so a return goes back to the same batch.\nCREATE TABLE IF NOT EXISTS \"order_item_batches\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"order_item_id\"            INTEGER  NOT NULL REFERENCES \"order_items\"(\"id\") ON DELETE CASCADE,\n  \"batch_id\"                 INTEGER  REFERENCES \"stock_batches\"(\"id\") ON DELETE SET NULL,\n  \"qty_milli\"                INTEGER  NOT NULL,\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"order_item_batches_updated_at\" AFTER UPDATE ON \"order_item_batches\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"order_item_batches\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_order_item_batches_business_id\" ON \"order_item_batches\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_order_item_batches_order_item_id\" ON \"order_item_batches\" (\"order_item_id\");\nCREATE INDEX IF NOT EXISTS \"ix_order_item_batches_batch_id\" ON \"order_item_batches\" (\"batch_id\");\n\nCREATE TABLE IF NOT EXISTS \"sale_return_items\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"return_id\"                INTEGER  NOT NULL REFERENCES \"sale_returns\"(\"id\") ON DELETE CASCADE,\n  \"order_item_id\"            INTEGER  REFERENCES \"order_items\"(\"id\") ON DELETE SET NULL,\n  \"product_id\"               INTEGER  REFERENCES \"products\"(\"id\") ON DELETE SET NULL,\n  \"product_name\"             TEXT     NOT NULL,  -- max 150 · snapshot\n  \"unit\"                     TEXT     NOT NULL,  -- max 10\n  \"qty_milli\"                INTEGER  NOT NULL,\n  \"unit_price_minor\"         INTEGER  NOT NULL,\n  \"amount_minor\"             INTEGER  NOT NULL,  -- incl. tax, after the bill's discount share\n  \"restock\"                  INTEGER  NOT NULL DEFAULT 1 CHECK (\"restock\" IN (0, 1)),  -- false = damaged, not back on the shelf\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"sale_return_items_updated_at\" AFTER UPDATE ON \"sale_return_items\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"sale_return_items\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_sale_return_items_business_id\" ON \"sale_return_items\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_sale_return_items_return_id\" ON \"sale_return_items\" (\"return_id\");\nCREATE INDEX IF NOT EXISTS \"ix_sale_return_items_order_item_id\" ON \"sale_return_items\" (\"order_item_id\");\nCREATE INDEX IF NOT EXISTS \"ix_sale_return_items_product_id\" ON \"sale_return_items\" (\"product_id\");\n\nCREATE TABLE IF NOT EXISTS \"kitchen_ticket_items\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,  -- ROWID\n  \"business_id\"              INTEGER  NOT NULL,  -- → businesses.id in the platform database (checked by the API)\n  \"ticket_id\"                INTEGER  NOT NULL REFERENCES \"kitchen_tickets\"(\"id\") ON DELETE CASCADE,\n  \"order_item_id\"            INTEGER  REFERENCES \"order_items\"(\"id\") ON DELETE SET NULL,\n  \"name\"                     TEXT     NOT NULL,  -- max 150 · snapshot with size / add-ons\n  \"qty_milli\"                INTEGER  NOT NULL,\n  \"is_veg\"                   INTEGER  CHECK (\"is_veg\" IS NULL OR \"is_veg\" IN (0, 1)),\n  \"note\"                     TEXT,  -- max 150\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),  -- CREATEDTIME\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))  -- MODIFIEDTIME\n) STRICT;\n\nCREATE TRIGGER IF NOT EXISTS \"kitchen_ticket_items_updated_at\" AFTER UPDATE ON \"kitchen_ticket_items\" FOR EACH ROW WHEN NEW.\"updated_at\" = OLD.\"updated_at\"\nBEGIN UPDATE \"kitchen_ticket_items\" SET \"updated_at\" = (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) WHERE \"id\" = NEW.\"id\"; END;\n\nCREATE INDEX IF NOT EXISTS \"ix_kitchen_ticket_items_business_id\" ON \"kitchen_ticket_items\" (\"business_id\");\nCREATE INDEX IF NOT EXISTS \"ix_kitchen_ticket_items_ticket_id\" ON \"kitchen_ticket_items\" (\"ticket_id\");\nCREATE INDEX IF NOT EXISTS \"ix_kitchen_ticket_items_order_item_id\" ON \"kitchen_ticket_items\" (\"order_item_id\");\n\n-- =====================================================================================================\n--  Added for Turso\n-- =====================================================================================================\n\n-- Which migration files have run on this database.\nCREATE TABLE IF NOT EXISTS \"schema_migrations\" (\n  \"version\"                  TEXT     PRIMARY KEY,  -- file name, e.g. 0001_init\n  \"applied_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))\n) STRICT;\n\n-- Change feed: every committed write adds a row (same transaction); other devices ask \"what changed since\n-- <id>\" every ~15 s and re-read only those screens. Rows older than 2 days are removed by the daily job.\nCREATE TABLE IF NOT EXISTS \"change_log\" (\n  \"id\"                       INTEGER  PRIMARY KEY AUTOINCREMENT,\n  \"business_id\"              INTEGER  NOT NULL,\n  \"branch_id\"                INTEGER,             -- NULL = whole business\n  \"tag\"                      TEXT     NOT NULL,   -- orders · catalog · stock · customers · … (the app cache tags)\n  \"origin\"                   TEXT,                -- the device that made the change (it has already refreshed)\n  \"created_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))\n) STRICT;\nCREATE INDEX IF NOT EXISTS \"ix_change_log_created_at\" ON \"change_log\" (\"created_at\");\n\n-- Raised on every change to users, roles, branches, settings, the subscription or features → cached\n-- sign-in sessions reload. One row per shop (business_id kept so shops can share a database later).\nCREATE TABLE IF NOT EXISTS \"sync_epochs\" (\n  \"business_id\"              INTEGER  PRIMARY KEY,\n  \"epoch\"                    INTEGER  NOT NULL DEFAULT 1,\n  \"updated_at\"               TEXT     NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))\n) STRICT;\n"}]}
